'use strict';

const {rateLimitDelay} = require('./verification-wait.cjs');

// Backoff before each retry of a write that failed transiently: 2 s, 6 s, then 15 s (three retries after the
// first attempt). The review that precedes these calls is paid for, so a GitHub blip must not discard it.
const DELAYS_MS = Object.freeze([2000, 6000, 15000]);
// A rate limit that asks to wait longer than this is a hold, not a blip; it is reported as it always was.
const MAX_REQUESTED_WAIT_MS = 60000;
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));
// GitHub's own wording for a GraphQL failure that carries no cause ("Something went wrong while executing your
// query ... Please include EC12:..."), and the gateway timeouts it reports in the same channel.
const TRANSIENT_GRAPHQL = /something went wrong while executing your query|timed out|temporarily unavailable|try again/i;

// Transient: secondary or short rate limits, HTTP 5xx, and the unclassified GraphQL error above. Everything else
// (validation, permissions, "not mergeable", a protected-branch refusal) is deterministic and fails at once.
function isTransient(error) {
  const asked = rateLimitDelay(error);
  if (asked !== null) return asked <= MAX_REQUESTED_WAIT_MS;
  if (Number.isInteger(error?.status)) return error.status >= 500 && error.status < 600;
  const text = Array.isArray(error?.errors) ? error.errors.map(item => item?.message).join('\n') : String(error?.message ?? '');
  return TRANSIENT_GRAPHQL.test(text);
}

function describe(error) {
  const status = Number.isInteger(error?.status) ? `HTTP ${error.status}` : 'GraphQL error';
  const detail = String(error?.message ?? '').replaceAll('@', '').replace(/\s+/g, ' ').slice(0, 200);
  return `${status}: ${detail}`;
}

class TransientExhausted extends Error {
  constructor({operation, attempts, head, error}) {
    super(`GitHub kept failing transiently while ${operation} (${attempts} attempts; last ${describe(error)}). ` +
      `The Clouseau review of head ${head} was already accepted and nothing was lost: re-run only the failed job ` +
      `to repeat this step. Retrying it is safe and does not repeat the AI review.`);
    this.code = 'TRANSIENT_GITHUB'; this.attempts = attempts;
  }
}

// Runs `call(attempt)` and retries only transient failures with the bounded backoff. `call` receives the zero-based
// attempt so that a retry can first check whether an earlier, apparently failed attempt had in fact landed.
async function retryTransient(call, options, attempt = 0) {
  const {operation, head, wait = sleep, delays = DELAYS_MS, report = () => {}} = options;
  try {return await call(attempt);} catch (error) {
    if (!isTransient(error)) throw error;
    if (attempt >= delays.length) throw new TransientExhausted({operation, attempts: attempt + 1, head, error});
    const delay = Math.max(delays[attempt], rateLimitDelay(error) ?? 0);
    report(`Transient GitHub failure while ${operation} (${describe(error)}); retry ${attempt + 1}/${delays.length} in ${delay / 1000} s.`);
    await wait(delay);
    return retryTransient(call, options, attempt + 1);
  }
}

module.exports = {DELAYS_MS, MAX_REQUESTED_WAIT_MS, TransientExhausted, isTransient, retryTransient};

'use strict';

// A review job that polls for PR verification occupies a runner while it waits.
// On a runner pool with one slot the verification job it waits for is queued
// behind it and can never start. Waiting is bounded by progress: verification
// that is running is awaited, but one that has not started within the
// configured queue grace ends the review cleanly in a pending state. It holds
// no runner afterwards and is reassessed when the verification run completes.
const DEFAULT_QUEUE_GRACE_SECONDS = 900;
const MAX_QUEUE_GRACE_SECONDS = 3600;
const POLL_MS = 15000;

const graceSeconds = config => config.verification_queue_grace_seconds ?? DEFAULT_QUEUE_GRACE_SECONDS;

const WAITING_REASON = 'Waiting for verification: PR verification had not started within the queue grace, so this review ended ' +
  'without holding a runner and made no decision. It is reassessed automatically when the PR verification run completes; ' +
  'otherwise re-run this workflow after verification completes, or push a new head.';

// Polling is paid for from the repository's shared REST budget (1000 requests per hour for the
// installation token), so it is deliberately cheap: a running verification is polled every POLL_MS,
// an absent or queued one with exponentially growing gaps (15, 30, 60 s, then 120 s), because nothing
// can change faster than a runner starts and the completed run reassesses the PR by itself.
const MAX_IDLE_POLL_MS = 120000;

// Returns a function called with each pending verification state. It returns the next delay and
// whether verification has been absent or queued for longer than the grace (measured in waited time).
function pollSchedule(seconds) {
  let idle = 0; let waited = 0;
  return state => {
    if (state === 'running') {idle = 0; waited = 0; return {stalled: false, delay: POLL_MS};}
    if (waited >= seconds * 1000) return {stalled: true, delay: 0};
    const delay = Math.min(POLL_MS * 2 ** idle++, MAX_IDLE_POLL_MS);
    waited += delay;
    return {stalled: false, delay};
  };
}

// GitHub signals an exhausted budget with 429, or 403 carrying retry-after, x-ratelimit-remaining: 0, or a
// primary/secondary rate-limit message. Returns the milliseconds the response asks us to wait (0 when
// it states none), or null when the error is not a rate limit at all.
function rateLimitDelay(error, now = Date.now()) {
  const headers = error?.response?.headers ?? {};
  const message = String(error?.message ?? '');
  const limited = error?.status === 429 || (error?.status === 403 &&
    (headers['retry-after'] !== undefined || headers['x-ratelimit-remaining'] === '0' || /rate limit|abuse detection|secondary rate/i.test(message)));
  if (!limited) return null;
  if (headers['retry-after'] !== undefined) return Math.max(0, Number(headers['retry-after']) * 1000);
  if (headers['x-ratelimit-remaining'] === '0' && headers['x-ratelimit-reset'] !== undefined) return Math.max(0, Number(headers['x-ratelimit-reset']) * 1000 - now);
  return 0;
}

class RateLimitHold extends Error {
  constructor(resetAt) {
    super('GitHub API rate limit exhausted');
    this.code = 'RATE_LIMIT'; this.resetAt = resetAt;
  }
}

// Retries a read-only or idempotent call that hit a rate limit. The wait is the larger of what GitHub
// asked for and a bounded exponential backoff, plus jitter so that many PRs do not wake together. If
// the wait needed would exceed the remaining budget the call ends in a RateLimitHold stating when to retry.
async function withRateLimit(call, options, attempt = 0, waited = 0) {
  const {wait, now = Date.now, random = Math.random, maxAttempts = 8, maxWaitMs = 20 * 60000, report = () => {}} = options;
  try {return await call();} catch (error) {
    const asked = rateLimitDelay(error, now());
    if (asked === null) throw error;
    const delay = Math.max(asked, Math.min(2 ** attempt * 1000, 60000)) + Math.floor(random() * 1000);
    if (attempt + 1 >= maxAttempts || waited + delay > maxWaitMs) throw new RateLimitHold(now() + Math.max(asked, delay));
    report(`GitHub API rate limit: waiting ${Math.ceil(delay / 1000)} s before retry ${attempt + 1}/${maxAttempts - 1}`);
    await wait(delay);
    return withRateLimit(call, options, attempt + 1, waited + delay);
  }
}

// The PR head named by the event payload, or empty when the event (a manual dispatch) carries none.
const headShaOf = context => context.payload.pull_request?.head?.sha ?? '';

// A conditional GET: an unchanged answer is HTTP 304, which is served from the cache and does not count against
// the primary rate limit. `request` receives extra headers (an If-None-Match when a cached answer exists).
async function conditionalGet(cache, key, request) {
  const cached = cache.get(key);
  let response;
  try {response = await request(cached ? {'if-none-match': cached.etag} : {});} catch (error) {
    if (error.status !== 304 || !cached) throw error;
    return {data: cached.data, headers: {}};
  }
  if (response.headers?.etag) cache.set(key, {etag: response.headers.etag, data: response.data});
  return response;
}

const heldReason = hold => `Held: GitHub API rate limit, will retry after ${new Date(hold.resetAt).toISOString()}.`;

module.exports = {DEFAULT_QUEUE_GRACE_SECONDS, MAX_QUEUE_GRACE_SECONDS, MAX_IDLE_POLL_MS, POLL_MS, WAITING_REASON, graceSeconds,
  pollSchedule, rateLimitDelay, RateLimitHold, withRateLimit, heldReason, headShaOf, conditionalGet};

'use strict';

const fs = require('node:fs');
const {readPull} = require('./pull-read.cjs');
const branchConflict = require('./branch-conflict.cjs');
const {requestReview} = require('./provider.cjs');
const {retryTransient} = require('./transient-retry.cjs');
const {pollSchedule, graceSeconds, WAITING_REASON, withRateLimit, RateLimitHold, heldReason, headShaOf, conditionalGet} = require('./verification-wait.cjs');

// Whether the protected `local_review` lets an owner confirmation follow the diff: only `confirmation: "diff"` together with
// `binding: "diff"` (validateTrust refuses any other combination).
const confirmationFollowsDiff = localReview => localReview?.binding === 'diff' && localReview?.confirmation === 'diff';

// The commit an `/approve-intent <sha>` comment names, with the text it confirms; null for anything else.
function intentAny(body) {
  if (typeof body !== 'string') return null;
  const match = /^\/approve-intent ([a-f0-9]{40})(?:\n\nAccepted purpose:\n([\s\S]*\S))?$/.exec(body.trim());
  return match ? {sha: match[1], text: intentText(body, match[1])} : null;
}

function intentText(body, sha) {
  if (typeof body !== 'string' || !/^[a-f0-9]{40}$/.test(sha)) return null;
  const match = new RegExp(`^/approve-intent ${sha}(?:\\n\\nAccepted purpose:\\n([\\s\\S]*\\S))?$`).exec(body.trim());
  if (!match) return null;
  return {body: match[0], ...(match[1] ? {accepted_purpose: match[1].trim()} : {})};
}

function matchesPath(filename, paths) {
  return paths.some(path => path.endsWith('/') ? filename.startsWith(path) : filename === path);
}

// The paths whose change needs exact-head owner confirmation. One list for CI scope checks and the local warning.
function controlPaths(config) {
  return [`.github/workflows/${config.workflow}`, '.github/ci/', '.github/clouseau.json', '.github/CODEOWNERS', 'CODEOWNERS', 'docs/CODEOWNERS',
    '.clouseau-local.json', config.repository_policy, 'AGENTS.md', ...config.sensitive_paths];
}

function protectedChanges(config, files) {
  const sensitive = controlPaths(config);
  return files.flatMap(file => [file.filename, file.previous_filename || ''])
    .filter((name, index, all) => name && matchesPath(name, sensitive) && all.indexOf(name) === index);
}

function createPolicy(input, {engine = null, codeownersRequired = false, manualMerge = false, privateOwnerAutomatic = false, attested = null, intentDiff = false} = {}) {
const config = require('./config.cjs').validateConfig(input);
if (config.version === 2) {
  const {local_review, merge_mode, exact_revert, hosted_review, ...legacyConfig} = config;
  // Required verification steps a workflow skipped count only when a fully valid receipt attests the verification (verification-attestation.cjs).
  const attested = (github, repo, pr) => require('./verification-attestation.cjs').receiptAttests({github, repo, pr, config, engine, explain: true});
  // Under the protected `local_review.confirmation: "diff"` (with `binding: "diff"`) an owner confirmation follows the diff as
  // a receipt does (confirms()). Absent, a confirmation names the exact head, as before.
  const legacy = createPolicy({...legacyConfig, version: 1}, {codeownersRequired: true, manualMerge: merge_mode === 'manual', privateOwnerAutomatic: merge_mode === 'automatic', attested,
    intentDiff: confirmationFollowsDiff(local_review)});
  return require('./acceptance-controller.cjs').createAcceptancePolicy(config, legacy, engine);
}
const COVERAGE = require('./coverage-changed.cjs').requirement(config);
const CHECK = 'approval-policy';
const WORKFLOW = config.workflow;
const MANUAL_REVIEWER = config.manual_reviewer;
const VERIFY_STEPS = config.verification.steps;
const EMPTY_BLOB = 'e69de29bb2d1d6434b8b29ae775ad8c2e48c5391';
const NEVER_ARMED = Object.freeze(['review_incomplete', 'repair_required', 'blocked_technical', 'blocked_integrity']);
const REVIEW_CONTROL_REASON = 'Review controls or a protected repository-purpose contract changed';
const DISABLE_AUTO_MERGE = 'mutation($id:ID!) { disablePullRequestAutoMerge(input:{pullRequestId:$id}) { pullRequest { id } } }';
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

function numberFor(context) {
  const value = context.payload.pull_request?.number ||
    (context.payload.issue?.pull_request && context.payload.issue.number) || process.env.PR_NUMBER;
  if (!/^[1-9][0-9]*$/.test(String(value))) throw new Error('A PR number is required');
  return Number(value);
}

// `exempt` names the protected files whose change was verified as the opt-in managed-standard update (managed-agents.cjs).
// `protect` names the files that are protected only because of what changed in them (declared coverage thresholds).
function scopeReason(files, pr, exempt = new Set(), protect = new Set()) {
  if (files.length !== pr.changed_files || files.length === 0) return 'Incomplete changed-file list';
  const sensitive = controlPaths(config);
  const protectedFile = name => (matchesPath(name, sensitive) && !exempt.has(name)) || protect.has(name);
  if (files.some(file => protectedFile(file.filename) || protect.has(file.previous_filename) || matchesPath(file.previous_filename || '', sensitive))) {
    return REVIEW_CONTROL_REASON;
  }
  // GitHub lists no patch for an empty added file. Its empty blob id is the proof that no text was withheld.
  const emptyAdded = file => file.status === 'added' && file.sha === EMPTY_BLOB && file.changes === 0;
  if (files.some(file => (!file.patch && !emptyAdded(file)) || !['added', 'modified', 'removed', 'renamed'].includes(file.status))) {
    return 'Incomplete patch or unsupported file change';
